import Foundation
import Network
import Security

/// Is the TLS peer a genuine Bambu printer, and the one the user set up? Used by the camera and the MQTT client
/// so the access code (which also grants full control of the printer) only ever goes to the right device.
/// 1. The certificate must chain to a Bambu CA (bundled below).
/// 2. Its serial number (the certificate's common name) must match the one seen on the first connection
///    (trust on first use). Saving the settings forgets it, which is how the user accepts a new printer.
enum PrinterTrust {
    enum Failure: Error {
        case notBambu
        case otherPrinter(serial: String)

        var message: String {
            switch self {
            case .notBambu:
                return String(localized: "Connection refused: this device is not a genuine Bambu printer.", bundle: AppLanguage.bundle)
            case .otherPrinter(let serial):
                return String(localized: "This is not the printer you set up (serial \(serial)). Save the settings again to use it.",
                              bundle: AppLanguage.bundle)
            }
        }
    }

    static let serialKey = "printerSerial"

    /// Returns the printer serial, or why the peer must be rejected.
    static func check(_ trust: sec_trust_t) -> Result<String, Failure> {
        let secTrust = sec_trust_copy_ref(trust).takeRetainedValue()
        SecTrustSetPolicies(secTrust, SecPolicyCreateBasicX509()) // printers are reached by IP: no host name to match
        SecTrustSetAnchorCertificates(secTrust, anchors as CFArray)
        SecTrustSetAnchorCertificatesOnly(secTrust, true)
        // ponytail: identity, not freshness. "BBL CA" expires in 2032 but signs printer certificates valid until 2035,
        // so evaluate no later than its last valid month. Revisit if Bambu ships a replacement CA.
        SecTrustSetVerifyDate(secTrust, min(Date(), Date(timeIntervalSince1970: 1_961_712_000)) as CFDate) // 2032-03-01
        guard SecTrustEvaluateWithError(secTrust, nil),
              let leaf = (SecTrustCopyCertificateChain(secTrust) as? [SecCertificate])?.first else { return .failure(.notBambu) }
        var name: CFString?
        SecCertificateCopyCommonName(leaf, &name)
        guard let serial = name as String?, !serial.isEmpty else { return .failure(.notBambu) }
        if let known = UserDefaults.standard.string(forKey: serialKey), known != serial {
            return .failure(.otherPrinter(serial: serial))
        }
        UserDefaults.standard.set(serial, forKey: serialKey)
        return .success(serial)
    }

    /// Bambu Lab CA certificates (DER, base64), from ha-bambulab's pybambu/certs/bambu.cert.
    private static let anchors: [SecCertificate] = [
        // BBL CA2 RSA, expires Jun 17 01:38:08 2050 GMT
        "",
        // BBL CA2 ECC, expires Jun 17 01:38:35 2050 GMT
        "",
        // BBL CA2 RSA, expires Jun 15 02:01:27 2035 GMT
        "",
        // BBL CA2 ECC, expires Jun 15 02:01:47 2035 GMT
        "",
        // BBL CA, expires Apr  1 03:42:11 2032 GMT
        "",
    ].compactMap { Data(base64Encoded: $0).flatMap { SecCertificateCreateWithData(nil, $0 as CFData) } }
}
